def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0])
    visited = set()
    path = []

    def is_valid(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.' and (row, col) not in visited

    def dfs(row, col):
        if (row, col) == goal:
            path.append((row, col))
            return True

        visited.add((row, col))
        path.append((row, col))

        # Explore neighbors
        neighbors = [(row + 1, col), (row - 1, col), (row, col + 1), (row, col - 1)]
        for next_row, next_col in neighbors:
            if is_valid(next_row, next_col):
                if dfs(next_row, next_col):
                    return True

        path.pop()
        return False

    if not is_valid(start[0], start[1]) or not is_valid(goal[0], goal[1]):
        return []

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]

    if dfs(start[0], start[1]):
        return path
    else:
        return []
